import sys

def solve_brute(n):
    res = []
    board = [[0] * n for _ in range(n)]

    def can_place(r, c):
        for i in range(r):
            if board[i][c]:
                return False
        for i in range(r):
            d = r - i
            if c - d >= 0 and board[i][c - d]:
                return False
            if c + d < n and board[i][c + d]:
                return False
        return True

    def backtrack(r):
        if r == n:
            res.append([row[:] for row in board])
            return
        for c in range(n):
            if can_place(r, c):
                board[r][c] = 1
                backtrack(r + 1)
                board[r][c] = 0

    backtrack(0)
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    for board in solve_brute(n):
        for row in board:
            print(' '.join(map(str, row)))

import sys

def solve_opt(n):
    res = []
    cols = [0] * n
    diag1 = [0] * (2 * n - 1)
    diag2 = [0] * (2 * n - 1)
    queens = [-1] * n

    def backtrack(r):
        if r == n:
            board = [[0] * n for _ in range(n)]
            for i in range(n):
                board[i][queens[i]] = 1
            res.append(board)
            return
        for c in range(n):
            if cols[c] or diag1[r + c] or diag2[r - c + n - 1]:
                continue
            queens[r] = c
            cols[c] = diag1[r + c] = diag2[r - c + n - 1] = 1
            backtrack(r + 1)
            cols[c] = diag1[r + c] = diag2[r - c + n - 1] = 0

    backtrack(0)
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    for board in solve_opt(n):
        for row in board:
            print(' '.join(map(str, row)))

import sys

def solve_best(n):
    res = []
    queens = [-1] * n

    def backtrack(r, cols, d1, d2):
        if r == n:
            board = [[0] * n for _ in range(n)]
            for i in range(n):
                board[i][queens[i]] = 1
            res.append(board)
            return
        for c in range(n):
            if (cols >> c) & 1 or (d1 >> (r + c)) & 1 or (d2 >> (r - c + n - 1)) & 1:
                continue
            queens[r] = c
            backtrack(r + 1, cols | (1 << c), d1 | (1 << (r + c)), d2 | (1 << (r - c + n - 1)))

    backtrack(0, 0, 0, 0)
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    for board in solve_best(n):
        for row in board:
            print(' '.join(map(str, row)))
